  glossary: [
    { term: "Day 0", definition: "Pre-kickoff preparation: definition, readiness, access, authority and evidence gathering before any account is operated." },
    { term: "Day 1", definition: "Stand-up and transition: the operator capability is established and the first accounts are taken on under the opened gate." },
    { term: "Day 2", definition: "Steady-state run: ongoing operation, support, optimisation and account growth under the operator model." },
    { term: "Controlled Operator Pilot", definition: "The first live phase, run on a deliberately limited account population to prove the operating and economic model before scale." },
    { term: "Gate", definition: "A decision point with unlock conditions that must be evidenced before the next phase begins. G0 is a readiness gate; G1 to G4 are formal decision gates." },
    { term: "No-Partner Account", definition: "An in-scope account with no incumbent partner engagement, and therefore the simplest operator treatment." },
    { term: "Incumbent Partner", definition: "An existing partner already engaged in an account, whose presence changes engagement rights, economics and sequencing." },
    { term: "Activation Fund", definition: "Proposed funding to stand up the operator capability. Proposed only — not confirmed, and not assumed to be cash at kickoff." },
    { term: "Managed Services", definition: "Ongoing operated services delivered under the operator model, subject to confirmed services rights." },
    { term: "Professional Services", definition: "Project-based delivery services, subject to confirmed rights to sell and deliver into the account." },
    { term: "MBG", definition: "Minimum Business Guarantee — a proposed shared-risk mechanic setting a floor on business volume or value for qualifying accounts." },
    { term: "Operator Authority", definition: "The decision rights, data access and control granted to Neurealm to run in-scope accounts." },
  ],
